export function measureText(e,n){let t=0;for(let r=0;r<n.length;r++)if(e.chars[n[r]]){const o=e.kernings[n[r]]&&e.kernings[n[r]][n[r+1]]?e.kernings[n[r]][n[r+1]]:0;t+=(e.chars[n[r]].xadvance||0)+o}return t}export function measureTextHeight(e,n,t){const r=n.split(" ");let o="",i=e.common.lineHeight;for(let n=0;n<r.length;n++){const s=o+r[n]+" ";measureText(e,s)>t&&n>0?(i+=e.common.lineHeight,o=r[n]+" "):o=s}return i}